from core import greet
from fastapi import FastAPI

app = FastAPI()


@app.get("/health")
def health() -> dict[str, bool]:
    return {"ok": True}


@app.get("/greet/{name}")
def greet_route(name: str) -> dict[str, str]:
    return {"message": greet(name)}

"""Shared code: no web framework here, so any app can use it."""


def greet(name: str) -> str:
    return f"Hello, {name}!"

from core import greet


def test_greet() -> None:
    assert greet("Ana") == "Hello, Ana!"
